{"test_cases": [
    {"id": "TC1", "title": "Test password length between 8 and 64 characters", "type": "positive", "preconditions": "User is logged in and on the account page", "steps": ["Enter a password that is 8 characters long", "Enter a password that is 64 characters long"], "expected_result": "The password is accepted and the user sees the 'Password updated' message", "covers": ["AC1"]},
    {"id": "TC2", "title": "Test password length just below 8 characters", "type": "boundary", "preconditions": "User is logged in and on the account page", "steps": ["Enter a password that is 7 characters long"], "expected_result": "The password is rejected and the user sees an error message", "covers": ["AC1"]},
    {"id": "TC3", "title": "Test password length just above 64 characters", "type": "boundary", "preconditions": "User is logged in and on the account page", "steps": ["Enter a password that is 65 characters long"], "expected_result": "The password is rejected and the user sees an error message", "covers": ["AC1"]},
    {"id": "TC4", "title": "Test password with only letters and no digits", "type": "negative", "preconditions": "User is logged in and on the account page", "steps": ["Enter a password that consists only of letters and no digits"], "expected_result": "The password is rejected and the user sees an error message", "covers": ["AC1", "AC2"]},
    {"id": "TC5", "title": "Test password with only digits and no letters", "type": "negative", "preconditions": "User is logged in and on the account page", "steps": ["Enter a password that consists only of digits and no letters"], "expected_result": "The password is rejected and the user sees an error message", "covers": ["AC1", "AC2"]},
    {"id": "TC6", "title": "Test password with letters and digits, but the same as the current password", "type": "negative", "preconditions": "User is logged in and on the account page", "steps": ["Enter a password that is the same as the current password"], "expected_result": "The password is rejected and the user sees an error message", "covers": ["AC1", "AC3"]},
    {"id": "TC7", "title": "Test successful password change", "type": "positive", "preconditions": "User is logged in and on the account page", "steps": ["Enter a valid password that meets all requirements"], "expected_result": "The password is accepted and the user sees the 'Password updated' message", "covers": ["AC1", "AC2", "AC3"]}
]}
